#!/usr/bin/env python3
"""Whole-page DNA kits reverse-engineered from named references in the Charlie Hills corpus.

`charlie_kit` gives loose components. This module gives complete skeletons: each function
reproduces one catalogued reference's zones, proportions and reading order, and takes only content.
Borrowing a whole skeleton is what keeps a dense graphic legible, because the reading order was
designed once and is not reinvented per post.

Each kit names its source reference. Check it before changing one.
"""
from __future__ import annotations

from charlie_kit import DARK, LIGHT, _CSS, avatar_data_uri, icon, logos, up  # noqa: F401

# ---------------------------------------------------------------------------- shared chrome

STAR = ('<svg viewBox="0 0 40 40" style="width:{s}px;height:{s}px;flex-shrink:0">'
        '<g fill="{c}"><rect x="18" y="0" width="4" height="40" rx="2"/>'
        '<rect x="0" y="18" width="40" height="4" rx="2"/>'
        '<rect x="18" y="0" width="4" height="40" rx="2" transform="rotate(45 20 20)"/>'
        '<rect x="18" y="0" width="4" height="40" rx="2" transform="rotate(-45 20 20)"/>'
        '<rect x="18" y="0" width="4" height="40" rx="2" transform="rotate(22.5 20 20)"/>'
        '<rect x="18" y="0" width="4" height="40" rx="2" transform="rotate(-22.5 20 20)"/>'
        '<rect x="18" y="0" width="4" height="40" rx="2" transform="rotate(67.5 20 20)"/>'
        '<rect x="18" y="0" width="4" height="40" rx="2" transform="rotate(-67.5 20 20)"/>'
        '</g></svg>')


def _shell(theme: dict, accent: str, extra_css: str, body: str,
           footer: str) -> str:
    t = dict(theme)
    t["ac"] = accent
    vars_ = ";".join(f"--{k}:{v}" for k, v in t.items())
    return (f'<!doctype html><html><head><meta charset="utf-8">'
            f'<style>:root{{{vars_}}}{_CSS}{extra_css}</style></head><body>'
            f'{body}{footer}</body></html>')


def _footer(name: str, line: str, handle: str, avatar: str, dark_strip: bool = True) -> str:
    bg = "var(--foot)" if dark_strip else "#FFFFFF"
    return (f'<div class="foot" style="background:{bg}">'
            f'<img src="{avatar}">'
            f'<div class="t">Follow <b>{name}</b> {line} <i>{handle}</i></div>'
            f'<div class="rp">&#8635; REPOST</div></div>')


# ---------------------------------------------------------------------------- KIT A
# source: 36-e2371.jpg  "code-vs-plain-english-columns"
# zones: title band .16 | column header row .06 | paired rows .68 | footer line .10
# reading order: title, column heads, then row by row left to right across a dotted leader.

KIT_A_CSS = """
.a-top{display:flex;align-items:flex-start;gap:18px;padding:26px 40px 0}
.a-ttl{font-size:30px;font-weight:500;letter-spacing:-.5px;line-height:1.05;color:var(--dim2)}
.a-ttl b{display:block;font-size:56px;font-weight:900;letter-spacing:-2px;color:var(--ink)}
.a-sub{font-size:17px;color:var(--dim);margin-top:7px}
.a-badge{margin-left:auto;display:flex;align-items:center;gap:11px;text-align:right}
.a-badge img{width:56px;height:56px;border-radius:50%;object-fit:cover}
.a-badge div b{display:block;font-size:14px;font-weight:800;letter-spacing:.6px;color:var(--ink)}
.a-badge div s{display:block;text-decoration:none;font-family:'JetBrains Mono',monospace;
 font-size:11.5px;color:var(--ac);letter-spacing:.2px;margin-top:2px}
.a-heads{display:flex;gap:0;padding:16px 40px 0}
.a-heads span{font-family:'JetBrains Mono',monospace;font-size:12px;font-weight:600;
 letter-spacing:1.1px;color:var(--dim)}
.a-grid{display:flex;gap:0;padding:9px 40px 0;align-items:stretch}
.a-doc{width:556px;flex-shrink:0;background:#12141C;border-radius:9px;overflow:hidden;
 display:flex;flex-direction:column}
.a-bar{background:#1B1E29;padding:8px 12px;display:flex;align-items:center;gap:7px}
.a-bar i{width:10px;height:10px;border-radius:50%;display:block}
.a-tab{margin-left:9px;background:#12141C;border-radius:5px 5px 0 0;padding:4px 12px;
 font-family:'JetBrains Mono',monospace;font-size:12px;color:#C9D1E4}
.a-stamp{margin-left:auto;font-family:'JetBrains Mono',monospace;font-size:10.5px;font-weight:600;
 letter-spacing:.6px;color:#8A93A8;border:1.5px solid #3A4056;border-radius:4px;padding:2px 7px;
 transform:rotate(-3deg)}
.a-body{display:flex;flex:1}
.a-rail{width:38px;background:#1B1E29;display:flex;flex-direction:column;align-items:center;
 padding-top:11px;gap:15px}
.a-lines{flex:1;padding:11px 14px 12px}
.a-line{display:flex;gap:9px;align-items:baseline}
.a-line .n{font-family:'JetBrains Mono',monospace;font-size:12px;color:#5C6480;width:15px;
 flex-shrink:0;text-align:right}
.a-line .h{font-family:'JetBrains Mono',monospace;font-size:15px;font-weight:600;color:#7FD6A0}
.a-line.no .h{color:#F2777A}
.a-note{font-family:'JetBrains Mono',monospace;font-size:12.5px;color:#8A93A8;
 margin:1px 0 6px 24px;line-height:1.35}
.a-right{flex:1;padding-left:16px;display:flex;flex-direction:column}
.a-pair{display:flex;align-items:flex-start;gap:9px;padding:6px 0}
.a-lead{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--line);letter-spacing:1px;
 padding-top:3px;flex-shrink:0}
.a-txt{font-size:16.5px;line-height:1.3;color:var(--dim2)}
.a-txt em{font-style:normal;background:#FFE9A3;color:#12100C;font-weight:700;
 padding:0 3px;border-radius:2px;box-decoration-break:clone}
.a-foot{padding:12px 40px 0;font-size:16px;font-style:italic;color:var(--dim);
 border-top:1px solid var(--line);margin:12px 40px 0}
"""


def kit_a_paired_rows(*, title_light: str, title_heavy: str, sub: str, badge: tuple[str, str],
                      avatar: str, doc_name: str, stamp: str, col_heads: tuple[str, str],
                      rows: list[dict], closing: str, footer: tuple[str, str, str],
                      accent: str, theme: dict | None = None) -> str:
    """Kit A. Each row is one document line on the left and one plain-English read on the right,
    joined by a dotted leader. `rows` items: {"h": headline, "no": bool, "notes": [str],
    "right": str with <em> marking the highlighted phrase}."""
    left, right = [], []
    for i, r in enumerate(rows, 1):
        cls = " no" if r.get("no") else ""
        left.append(f'<div class="a-line{cls}"><span class="n">{i}</span>'
                    f'<span class="h">{r["h"]}</span></div>')
        for nt in r.get("notes", []):
            left.append(f'<div class="a-note">{nt}</div>')
        right.append(f'<div class="a-pair"><span class="a-lead">&middot;&middot;&middot;&middot;</span>'
                     f'<span class="a-txt">{r["right"]}</span></div>')
    rail = "".join(icon(d, 17) for d in _RAIL_ICONS)
    body = (
        f'<div class="a-top">{STAR.format(s=34, c=accent)}'
        f'<div><div class="a-ttl">{title_light}<b>{title_heavy}</b></div>'
        f'<div class="a-sub">{sub}</div></div>'
        f'<div class="a-badge"><div><b>{up(badge[0])}</b><s>{badge[1]}</s></div>'
        f'<img src="{avatar}"></div></div>'
        f'<div class="a-heads"><span style="width:556px;flex-shrink:0">{up(col_heads[0])}</span>'
        f'<span style="padding-left:16px">{up(col_heads[1])}</span></div>'
        f'<div class="a-grid"><div class="a-doc">'
        f'<div class="a-bar"><i style="background:#FF5F57"></i><i style="background:#FEBC2E"></i>'
        f'<i style="background:#28C840"></i><span class="a-tab">{doc_name}</span>'
        f'<span class="a-stamp">{up(stamp)}</span></div>'
        f'<div class="a-body"><div class="a-rail">{rail}</div>'
        f'<div class="a-lines">{"".join(left)}</div></div></div>'
        f'<div class="a-right">{"".join(right)}</div></div>'
        f'<div class="a-foot">{closing}</div>')
    return _shell(theme or LIGHT, accent, KIT_A_CSS, body,
                  _footer(*footer, avatar, dark_strip=False))


_RAIL_ICONS = [
    '<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>',
    '<circle cx="11" cy="11" r="7"/><path d="M20 20l-4.5-4.5"/>',
    '<path d="M4 6h16M4 12h10M4 18h13"/>',
    '<path d="M5 3l14 9-14 9V3z"/>',
    '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/>'
    '<rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',
]


# ---------------------------------------------------------------------------- KIT B
# source: 58-e2108.jpg  "two-column-command-grid"
# zones: title band .14 | card grid .76 | footer strip .10
# reading order: title, then down the left column card by card, then down the right column.

KIT_B_CSS = """
.b-top{padding:28px 40px 0;display:flex;align-items:flex-start;gap:16px}
.b-ttl{font-size:47px;font-weight:900;letter-spacing:-1.6px;line-height:1.02}
.b-ttl em{font-style:normal;color:var(--ac)}
.b-by{font-family:'JetBrains Mono',monospace;font-size:12.5px;font-weight:600;letter-spacing:1px;
 color:var(--dim);margin-top:8px}
.b-by span{color:var(--ac)}
.b-legend{margin-left:auto;text-align:right}
.b-legend div{display:flex;align-items:center;justify-content:flex-end;gap:7px;
 font-family:'JetBrains Mono',monospace;font-size:11.5px;color:var(--dim);margin-top:5px}
.b-legend i{width:11px;height:11px;border-radius:3px;display:block}
.b-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px;padding:18px 40px 0}
.b-card{background:var(--card);border:1px solid var(--line);border-radius:9px;
 padding:11px 13px 12px;position:relative}
.b-card.cool{opacity:.72}
.b-h{display:flex;align-items:center;gap:9px}
.b-n{width:22px;height:22px;border-radius:50%;border:1.5px solid var(--ac);color:var(--ac);
 font-size:11.5px;font-weight:800;display:flex;align-items:center;justify-content:center;
 flex-shrink:0}
.b-card.cool .b-n{border-color:var(--chipg);color:var(--dim)}
.b-l{font-family:'JetBrains Mono',monospace;font-size:16.5px;font-weight:600;color:var(--ac)}
.b-card.cool .b-l{color:var(--dim2)}
.b-dot{position:absolute;top:12px;right:12px;width:18px;height:18px;border-radius:50%;
 background:var(--ac);display:flex;align-items:center;justify-content:center;font-size:10px;
 font-weight:900;color:#fff}
.b-card.cool .b-dot{background:var(--chipg);color:var(--dim)}
.b-b{font-size:15.5px;line-height:1.34;color:var(--dim);margin-top:7px}
.b-pay{margin:14px 40px 0;border-left:5px solid var(--ac);background:var(--card);
 border:1px solid var(--line);border-left-width:5px;border-radius:0 9px 9px 0;padding:13px 18px}
.b-pay b{display:block;font-size:22px;font-weight:800;line-height:1.22}
.b-pay s{display:block;text-decoration:none;font-size:16px;color:var(--dim);margin-top:5px}
"""


def kit_b_command_grid(*, title: str, byline: str, cards: list[dict], legend: list[tuple[str, str]],
                       payoff: tuple[str, str], footer: tuple[str, str, str], avatar: str,
