import React from 'react'
import { renderToStaticMarkup } from 'react-dom/server'
import { EmbeddedTweet } from 'react-tweet'
import fs from 'fs'
import path from 'path'

// usage: node --import ./register.mjs render.mjs [config.json]
// config: { text, out, likes, replies, created_at, name, screen_name, avatar }
const cfgPath = process.argv[2]
const cfg = cfgPath ? JSON.parse(fs.readFileSync(cfgPath, 'utf8')) : {}

const id = '1585841080431321088'
const res = await fetch(`https://react-tweet.vercel.app/api/tweet/${id}`)
const { data: t } = await res.json()

t.text = cfg.text ?? "Lost $1.6M of revenue to a war in 8 weeks.\n\nBooked two one-way tickets to San Francisco.\n\nSigned one of the largest claims companies in America.\n\nLinkedIn fan fiction, except it happened :)"
t.display_text_range = [0, t.text.length]
t.entities = { hashtags: [], urls: [], user_mentions: [], symbols: [] }
delete t.mediaDetails; delete t.photos; delete t.video; delete t.quoted_tweet; delete t.card
t.user.name = cfg.name ?? 'Alok Kumar'
t.user.screen_name = cfg.screen_name ?? 'alokhk'
t.user.verified = false
t.user.is_blue_verified = true
t.user.profile_image_url_https = 'AVATAR_MARKER'
t.created_at = cfg.created_at ?? '2026-07-20T16:41:00.000Z'
t.favorite_count = cfg.likes ?? 391
t.conversation_count = cfg.replies ?? 24

let html = renderToStaticMarkup(React.createElement(EmbeddedTweet, { tweet: t }))
const avatar = fs.readFileSync(cfg.avatar ?? '/Users/anshmamgain/Desktop/Snowball/clients/alok-kumar/drafts/images/_alok-avatar.jpg')
html = html.replaceAll('AVATAR_MARKER', 'data:image/jpeg;base64,' + avatar.toString('base64'))

// concatenate every css file react-tweet ships
const base = 'node_modules/react-tweet/dist'
const cssFiles = []
const walk = d => { for (const f of fs.readdirSync(d, { withFileTypes: true })) {
  const p = path.join(d, f.name)
  if (f.isDirectory()) walk(p)
  else if (f.name.endsWith('.css')) cssFiles.push(p)
}}
walk(base)
const css = cssFiles.map(f => {
  let txt = fs.readFileSync(f, 'utf8')
  if (!f.endsWith('.module.css')) return txt
  const key = path.basename(f).replace(/\.module\.css$/,'').replace(/[^A-Za-z0-9]/g,'-')
  const locals = new Set()
  for (const m of txt.matchAll(/\.([A-Za-z_][A-Za-z0-9_-]*)/g)) locals.add(m[1])
  for (const l of [...locals].sort((a,b)=>b.length-a.length)) {
    txt = txt.replace(new RegExp('\\.'+l+'(?![A-Za-z0-9_-])','g'), '.'+key+'__'+l)
  }
  return txt
}).join('\n')

const page = `<!doctype html><html><head><meta charset="utf-8"><style>${css}
body{margin:0;background:#ffffff;display:flex;justify-content:center;align-items:center;min-height:100vh;padding:48px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif}
.wrap{width:560px}
[class*="tweet-replies__"]{display:none!important}
</style></head><body><div class="wrap" data-theme="light">${html}</div></body></html>`
const outHtml = cfg.out ?? 'tweet-page.html'
fs.writeFileSync(outHtml, page)
console.log('rendered ok ->', outHtml)
