def kit_e_numbered_two_col(*, title: str, sub: str, mark: str, avatar: str, handle: str,
                           legend: list[tuple[str, str, str]], bands: list[dict],
                           payoff: tuple[str, str], footer: tuple[str, str, str],
                           accent: str, theme: dict | None = None) -> str:
    """Kit E. `bands` items: {"label": str, "colour": hex, "rows": [(head, sub, detail)]}.
    Rows are numbered continuously across bands, the way the reference numbers its 9 steps."""
    leg = "".join(
        f'<div class="e-lg" style="border-color:{c}"><b style="color:{c}">{n}</b>'
        f'<span>{up(t)}</span></div>' for n, t, c in legend)
    flow, i = [], 0
    for b in bands:
        flow.append(f'<div class="e-band" style="--bandc:{b["colour"]}">{up(b["label"])}</div>')
        for head, sb, detail in b["rows"]:
            i += 1
            flow.append(
                f'<div class="e-row" style="--rowc:{b["colour"]}">'
                f'<div class="e-n">{i}</div>'
                f'<div><div class="e-h">{head}</div><div class="e-s">{sb}</div></div>'
                f'<div class="e-d">{detail}</div></div>')
    body = (f'<div class="e-top"><div class="e-mark">{mark}</div>'
            f'<div><div class="e-ttl">{title}</div><div class="e-sub">{sub}</div></div>'
            f'<div class="e-meta"><img src="{avatar}"><div>{handle}</div></div></div>'
            f'<div class="e-legend">{leg}</div>'
            f'<div class="e-flow">{"".join(flow)}</div>'
            f'<div class="e-pay"><b>{payoff[0]}</b><s>{payoff[1]}</s></div>')
    return _shell(theme or LIGHT, accent, KIT_E_CSS, body,
                  _footer(*footer, avatar, dark_strip=False))
