"""Build Manish Keshwani's LinkedIn Growth Strategy deck.

Same 5-page A4 shape as the Alok and Nuha decks: black cover, then mission, positioning, the week
already built, and the content system with the ask list and the preview link.

Every number on page 2 and 3 is measured off his live feed, pulled 2026-07-30 via Unipile into
research/posts-live-2026-07-30.json. Nothing here is estimated.

  python3 clients/manish-keshwani/build-strategy-pdf.py
"""
from __future__ import annotations

import base64
import json
import re
import subprocess
from pathlib import Path

C = Path(__file__).resolve().parent
ROOT = C.parents[1]
FONTS = ROOT / "tools/fonts"
PREVIEW = "app.thesnowball.agency/preview-linkedin/manish-week1-v13"

INK, PAPER, MUTED = "#12100C", "#FFFFFF", "#6E6A60"
ACCENT, LINE, WASH = "#B5432F", "#E4E0D7", "#F7F5F0"


def b64font(name: str) -> str:
    return base64.b64encode((FONTS / name).read_bytes()).decode()


def b64img(p: Path, px: int = 900, quality: int = 82) -> str:
    from io import BytesIO

    from PIL import Image
    im = Image.open(p).convert("RGB")
    im.thumbnail((px, px))
    buf = BytesIO()
    im.save(buf, "JPEG", quality=quality, optimize=True)
    return "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode()


def b64png(p: Path, px: int = 500) -> str:
    from io import BytesIO

    from PIL import Image
    im = Image.open(p).convert("RGBA")
    im.thumbnail((px, px))
    buf = BytesIO()
    im.save(buf, "PNG", optimize=True)
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode()


# ------------------------------------------------------------------ measured from his live feed
FEED = json.loads((C / "research/posts-live-2026-07-30.json").read_text())["items"]
PROFILE = json.loads((C / "research/profile-live-2026-07-30.json").read_text())


def months(s: str) -> float:
    m = re.match(r"(\d+)(mo|yr|w|d)", s or "")
    if not m:
        return 99.0
    n, u = int(m.group(1)), m.group(2)
    return {"mo": n, "yr": n * 12, "w": n / 4.3, "d": n / 30}[u]


ANN = re.compile(r"grateful|thank|proud|delighted|honou?red|excited to|pleased to|recogni[sz]ed|"
                 r"featur|congratulat|welcome|celebrat|launch|hosted|glad", re.I)
rows = [(months(x.get("date", "")), x.get("reaction_counter", 0) or 0,
         x.get("comment_counter", 0) or 0, (x.get("text") or "")) for x in FEED]
span = max(r[0] for r in rows)
reacs = sorted(r[1] for r in rows)
FOLLOWERS = PROFILE.get("follower_count", 0)
STATS = {
    "followers": f"{FOLLOWERS:,}",
    "cadence": f"{len(rows)/span:.1f}",
    "median": str(reacs[len(reacs) // 2]),
    "er": f"{sum(reacs)/len(reacs)/FOLLOWERS*100:.1f}%",
    "silent": f"{sum(1 for r in rows if r[2] == 0)}/{len(rows)}",
}
ann = sorted(r[1] for r in rows if ANN.search(r[3][:200]))
pov = sorted(r[1] for r in rows if not ANN.search(r[3][:200]))
MED_ANN, MED_POV = ann[len(ann) // 2], pov[len(pov) // 2]

POSTS = [
    ("hired-him-at-18", "Our best salesperson does $3M a month"),
    ("scouting-not-signing", "Overlooked by somebody else"),
    ("cannot-fire-fast", "A startup weighs 2 things. I weigh 9"),
    ("two-month-leave-approval", "10 weeks to approve 1 day"),
    ("twenty-to-hundred", "Lightwave does $20M. It should do $100M"),
    ("trade-show-60-percent", "60 percent still start with a handshake"),
    ("credit-is-growth", "1 shop to 13, on credit"),
    ("ai-team-not-curious", "Tools nobody was using"),
    ("most-expensive-constraint", "Everything I touch gets 10x better"),
    ("ai-cannot-do-this-yet", "6 things are still stopping me"),
]

PILLARS = [
    ("THE OPERATOR", "4 a week", ACCENT,
     "How a 30 year old distribution business actually decides. Credit, hiring, process debt, "
     "the calls that do not fit a spreadsheet. This is the pillar that proves he runs a real "
     "company rather than talks about one."),
    ("THE MARKET", "3 a week", "#1F5F7A",
     "What brands get wrong entering the Middle East and Africa, and what the region actually "
     "rewards. Written for a brand principal deciding who to hand a market to."),
    ("INSIDE TLM", "1 a week", "#5B7A3A",
     "Capability, shown not claimed. T4, the DG facilities, 56 countries, 18 brands. The pillar "
     "that answers the only question a brand asks second: can they deliver."),
]

SHIP = [
    "We research, write and design a weekly batch.",
    "You open 1 preview link that looks exactly like LinkedIn.",
    "You flag anything with a single comment.",
    "Posts ship on the cadence above, from his profile.",
    "Monthly analytics, plus a strategy review.",
]

NEED = [
    ("The brand list", "Everything TLM distributes today, and the brands you want next. The "
                       "second list is the one the whole strategy points at."),
    ("Your onboarding philosophy", "What makes a brand worth taking on, in your words. This "
                                   "becomes the spine of the market pillar."),
    ("Brand collateral", "Logos, approved product imagery, anything a brand has cleared for "
                         "partner use."),
    ("ICP confirmation", "Confirm the reader we are writing for is the brand principal and the "
                         "channel director, not the reseller."),
    ("LinkedIn credentials", "So we can publish on the agreed cadence without a handoff every "
                             "time."),
    ("5 minutes of your time", "Banner, headline, about and featured section. We do the work, "
                               "you approve once."),
]


def page(n: int, kicker: str, headline: str, body: str) -> str:
    return (f'<section class="pg"><div class="ph"><span class="kick">{kicker}</span>'
            f'<img class="mark" src="{TLM}"></div>{body}'
            f'<div class="pf"><span>Snowball &middot; Confidential</span>'
            f'<span>LinkedIn Growth Strategy &middot; Manish Keshwani &middot; July 2026</span>'
            f'<span>{n}</span></div></section>')


TLM = b64png(C / "assets/tlm-logo-trim.png", 420)
FACE = b64img(C / "assets/manish-circle.png", 420)

# ---------------------------------------------------------------------------------------- page 2
stat_cells = "".join(
    f'<div class="st"><b>{v}</b><span>{k}</span></div>' for v, k in [
        (STATS["followers"], "followers today"),
        (STATS["cadence"], "posts per month"),
        (STATS["median"], "median reactions"),
        (STATS["er"], "engagement rate"),
    ])
mech = "".join(
    f'<div class="col"><span class="cn">{i:02d}</span><h4>{h}</h4><p>{b}</p></div>'
    for i, (h, b) in enumerate([
        ("Reach is the ceiling", f"{STATS['er']} engagement on {STATS['followers']} followers means "
                                 "the feed already works. There are simply not enough of the right "
                                 "people watching it yet."),
        ("The buyer is not here", "Resellers and retail buyers across Africa and the Gulf do not "
                                  "run their business on LinkedIn. No amount of posting reaches "
                                  "them."),
        ("The brand is here", "Vendor executives, channel directors and regional VPs live on this "
                              "platform. They are the ones deciding who gets a market."),
        ("Judgement travels", f"His posts carrying a point of view already outperform "
                              f"announcements by {round((MED_POV/MED_ANN-1)*100)} percent on his "
                              "own feed."),
        ("Inbound compounds", "A brand that has read him for 6 months arrives already convinced. "
                              "That is a shorter negotiation and a better first contract."),
    ], 1))
P2 = page(2, "The mission", "", f"""
<h1 class="hl">LinkedIn will not sell<br>a single container.<br><em>It will bring brands.</em></h1>
<p class="lede">TLM does not need more resellers found on a social platform, because that is not
where they are. What TLM needs is the next Ubiquiti, and the people who hand out those territories
read LinkedIn every morning. So we stop treating this feed as marketing and start treating it as
brand acquisition.</p>
<div class="stats">{stat_cells}</div>
<div class="lbl">Why this works, in 5 steps</div>
<div class="cols">{mech}</div>
<div class="call"><b>The single best performing post on his feed is about a brand.</b>
Ubiquiti's CEO at UWC London took 175 reactions, roughly 4x his median. The audience has already
told us what it wants.</div>""")

# ---------------------------------------------------------------------------------------- page 3
bar_max = max(MED_ANN, MED_POV)
P3 = page(3, "Positioning", "", f"""
<div class="posrow">
  <img class="face" src="{FACE}">
  <div>
    <h1 class="hl sm">The operator a brand<br><em>hands a market to.</em></h1>
    <p class="lede">Not a logistics commentator and not a thought leader. A managing director who
    has run distribution across 56 countries for 30 years, and who is unusually willing to show the
    reasoning behind a decision. That reasoning is the product. A brand principal reading 6 months
    of it knows exactly how TLM would treat their line.</p>
    <div class="tags"><span>18 brands</span><span>56 countries</span><span>240 people</span>
    <span>30 years</span></div>
  </div>
</div>
<div class="card">
  <div class="lbl">What his own feed already proves</div>
  <div class="bar"><span class="bl">Posts with a point of view</span>
    <div class="bt"><i style="width:{MED_POV/bar_max*100:.0f}%;background:{ACCENT}"></i></div>
    <span class="bv">{MED_POV} median</span></div>
  <div class="bar"><span class="bl">Announcements and thank yous</span>
    <div class="bt"><i style="width:{MED_ANN/bar_max*100:.0f}%;background:#B9B4A8"></i></div>
    <span class="bv">{MED_ANN} median</span></div>
  <p class="fine">Measured across his last {len(rows)} posts, pulled 30 July 2026. The gap is
  {round((MED_POV/MED_ANN-1)*100)} percent, and it points at exactly the content we are proposing.</p>
</div>
<div class="call2"><b>What we deliberately will not post.</b> No motivational content, no reposted
industry news without a take, and no gratitude posts. {STATS['silent']} of his posts drew zero
comments, and almost all of those were announcements.</div>""")

# ---------------------------------------------------------------------------------------- page 4
tiles = "".join(
    f'<figure><img src="{b64img(C / f"drafts/images/2026-07-30-{s}.jpg", 460, 70)}">'
    f'<figcaption>{cap}</figcaption></figure>' for s, cap in POSTS)
P4 = page(4, "Week one, already built", "", f"""
<h1 class="hl sm">10 posts. 10 visuals.<br><em>Zero minutes of your time.</em></h1>
<p class="lede">Written, fact checked and designed before this document reached you. Every claim
traces to the onboarding call on 24 July. 3 of them carry figures we want confirmed before they
publish, and those are flagged in the preview.</p>
<div class="grid">{tiles}</div>
<div class="cta"><b>See the full week, rendered exactly as LinkedIn will show it</b>
<span>{PREVIEW}</span></div>""")

# ---------------------------------------------------------------------------------------- page 5
pill = "".join(
    f'<div class="pill" style="--pc:{c}"><b>{h}</b><span>{n}</span><p>{d}</p></div>'
    for h, n, c, d in PILLARS)
ship = "".join(f'<li>{x}</li>' for x in SHIP)
need = "".join(f'<li><b>{h}</b>{d}</li>' for h, d in NEED)
P5 = page(5, "The content system", "", f"""
<h1 class="hl sm">Three pillars,<br><em>one cadence.</em></h1>
<p class="lede">8 posts a week, split so that every week says something about how he thinks, who
the region rewards, and what TLM can actually do. The mix is what turns a feed into an argument.</p>
<div class="pills">{pill}</div>
<div class="two">
  <div><div class="lbl">How posts ship</div><ul class="chk">{ship}</ul></div>
  <div><div class="lbl">What we still need from you</div><ul class="chk need">{need}</ul></div>
</div>
<div class="cta"><b>Week one is staged and waiting on credentials</b>
<span>{PREVIEW}</span></div>""")

